window.STUDY_DATA = {"modules": [{"id": 1, "title": "CodeIgniter foundations", "subtitle": "MVC · setup · routing · views", "framework": "CodeIgniter", "file": "IT0049 - M1 - CodeIgniter Foundations.pdf", "pages": 54, "notes": [{"title": "The MVC handoff", "body": "Browser → route → controller → model → controller → view → response. Model handles data; View presents it; Controller coordinates.", "page": 15}, {"title": "Know the folders", "body": "app/Controllers, app/Models, app/Views, and app/Config hold application code. public/ is the document root. writable/ holds logs and cache.", "page": 24}, {"title": "Routes choose the action", "body": "$routes->get('/about', 'Pages::about');\n$routes->get('/profile/(:num)', 'Pages::profile/$1');\n// Explicit routes choose the action; index() is not called before every method.", "page": 35}, {"title": "Data becomes variables", "body": "return view('about', ['name' => 'Pages']);\n// about.php receives $name.\nreturn view('directory-name/about');", "page": 49}, {"title": "Do not mix up the tools", "body": "CodeIgniter uses Spark. php spark serve starts the server. A base URL needs a trailing slash. Keep the server pointed at public/.", "page": 27}]}, {"id": 2, "title": "CodeIgniter data layer", "subtitle": "Configuration · models · queries", "framework": "CodeIgniter", "file": "IT0049 - M2 - CodeIgniter Data Layer.pdf", "pages": 36, "notes": [{"title": "Connection settings", "body": ".env overrides matching Database.php defaults. Know hostname, database, username, password, and DBDriver. Credentials stay out of shared version control.", "page": 10}, {"title": "A model describes its table", "body": "protected $table = 'tasks';\nprotected $primaryKey = 'id';\nprotected $allowedFields = ['title', 'status'];", "page": 20}, {"title": "Build, then retrieve", "body": "$tasks = $model->where('status', 'pending')\n    ->orderBy('created_at', 'DESC')->findAll();\n$task = $model->find($id); // null if absent", "page": 26}, {"title": "Display deliberately", "body": "return view('tasks/index', ['tasks' => $tasks]);\n// In the view, loop through $tasks and escape output:\nesc($task['title']);", "page": 30}, {"title": "A page load is not always a connection test", "body": "The module’s page-visit test requires a page that actually performs a database query. A static page can load without touching the database.", "page": 14}]}, {"id": 3, "title": "CI forms, uploads & CRUD", "subtitle": "Validation · records · attachments", "framework": "CodeIgniter", "file": "IT0049 - M3 - Forms, Validation, File Upload, and CRUD.pdf", "pages": 36, "notes": [{"title": "Validate before writing", "body": "$rules = ['title' => 'required|min_length[3]'];\nif (! $this->validate($rules)) {\n    return redirect()->back()->withInput();\n}", "page": 12}, {"title": "Preserve useful feedback", "body": "old('title', $task['title']);\nvalidation_show_error('title');\n// Match the form field name to the validation key.", "page": 14}, {"title": "The CRUD method map", "body": "$model->insert($data);\n$model->findAll();\n$model->find($id);\n$model->update($id, $data);\n$model->delete($id);", "page": 19}, {"title": "The upload pipeline", "body": "multipart/form-data → uploaded/max_size/mime_in validation → getFile() → getRandomName() → move() → save filename → construct display URL.", "page": 34}, {"title": "One field, several checks", "body": "'uploaded[attachment]'\n'max_size[attachment,2048]'\n'mime_in[attachment,image/jpeg,image/png]'\n// File rules are different from ordinary text rules.", "page": 26}]}, {"id": 4, "title": "CI authentication & sessions", "subtitle": "Login · passwords · filters", "framework": "CodeIgniter", "file": "IT0049 - M4 - CodeIgniter Authentication and Sessions.pdf", "pages": 36, "notes": [{"title": "Sessions remember small values", "body": "session()->set('username', 'admin');\nsession()->get('username');\nsession()->remove('username');\nsession()->destroy();", "page": 8}, {"title": "Flash data survives the redirect", "body": "session()->setFlashdata('message', 'Task added!');\nreturn redirect()->to('/tasks');\n// On the next request:\nsession()->getFlashdata('message');", "page": 10}, {"title": "Hash and verify are a pair", "body": "$hash = password_hash($plainPassword, PASSWORD_DEFAULT);\npassword_verify($typedPassword, $storedHash);\n// Store the hash, never the plain password.", "page": 19}, {"title": "Protect the route", "body": "AuthFilter implements FilterInterface. before() checks login state; register auth in app/Config/Filters.php and attach it to protected routes.", "page": 29}, {"title": "Identity is only one check", "body": "A login filter establishes authentication. Role and ownership checks require additional logic. Keep only user_id, username, and small login values in session.", "page": 31}]}, {"id": 5, "title": "Laravel foundations", "subtitle": "Artisan · routes · Blade", "framework": "Laravel", "file": "IT0049 - M5 - Laravel Foundations.pdf", "pages": 34, "notes": [{"title": "Find the Laravel equivalents", "body": "Routes: routes/web.php. Controllers: app/Http/Controllers. Views: resources/views/*.blade.php. Local settings: .env. Public entry point: public/.", "page": 20}, {"title": "Artisan commands", "body": "php artisan serve\nphp artisan list\nphp artisan route:list\nphp artisan make:controller PageController", "page": 26}, {"title": "Connect a page", "body": "Route::get('/about', [PageController::class, 'about']);\n// Controller:\nreturn view('about', ['course' => 'IT0049']);\n// Blade:\n{{ $course }}", "page": 27}, {"title": "Static pages and parameters", "body": "Route::view('/about', 'about');\nRoute::get('/tasks/{id}', function ($id) {\n    return 'Task ID: ' . $id;\n});", "page": 21}, {"title": "Escape normal output", "body": "{{ $title }} escapes its value. {!! $title !!} prints raw output and should not be used for untrusted input.", "page": 32}]}, {"id": 6, "title": "Laravel data layer", "subtitle": "Migrations · seeders · Eloquent", "framework": "Laravel", "file": "IT0049 - M6 - Laravel Data Layer.pdf", "pages": 34, "notes": [{"title": "Four database responsibilities", "body": "Settings live in .env; schema in migrations; sample data in seeders; record logic in Eloquent models.", "page": 6}, {"title": "Schema tools", "body": "$table->id();\n$table->string('title', 150);\n$table->string('status', 20)->default('pending');\n$table->timestamps();", "page": 10}, {"title": "Know the reset differences", "body": "migrate runs pending migrations. migrate:rollback undoes the last batch. migrate:fresh rebuilds all tables and erases existing data.", "page": 12}, {"title": "Eloquent retrieval", "body": "Task::all();\nTask::where('status', 'pending')\n    ->orderBy('created_at', 'desc')->get();\nTask::findOrFail($id);", "page": 24}, {"title": "Records become model objects", "body": "protected $fillable = ['title', 'status'];\nreturn view('tasks.index', compact('tasks'));\n// In Blade:\n@foreach ($tasks as $task)\n    {{ $task->title }}\n@endforeach", "page": 19}]}, {"id": 7, "title": "Laravel forms & uploads", "subtitle": "Requests · updates · storage", "framework": "Laravel", "file": "IT0049 - M7 - Laravel Forms, Validation, and File Upload.pdf", "pages": 35, "notes": [{"title": "Create versus store", "body": "GET /tasks/create calls create() to show a form. POST /tasks calls store() to accept the submitted data. Include @csrf.", "page": 8}, {"title": "Validation and feedback", "body": "$validated = $request->validate([\n    'title' => ['required', 'string', 'max:100'],\n]);\n// Blade: @error('title') ... {{ $message }} ... @enderror\n// old('title') restores submitted input.", "page": 13}, {"title": "Updates use method spoofing", "body": "<form method=\"POST\" action=\"...\">\n    @csrf\n    @method('PATCH')\n    <input name=\"title\" value=\"{{ old('title', $task->title) }}\">\n</form>", "page": 22}, {"title": "Public upload pipeline", "body": "$path = $request->file('attachment')\n    ->store('attachments', 'public');\n$task->update(['attachment' => $path]);\n// Run php artisan storage:link for public display.", "page": 25}, {"title": "Keep replacement files safe", "body": "Validate type and size first. Store the replacement successfully, update the saved path, and then clean up the old file. The final checklist clarifies the shortened example on page 28.", "page": 33}, {"title": "Move larger rule sets", "body": "php artisan make:request UpdateTaskRequest creates a Form Request class. Put the longer rules in rules() to keep the controller focused.", "page": 30}]}, {"id": 8, "title": "Laravel CRUD, auth & email", "subtitle": "Resources · access · mail", "framework": "Laravel", "file": "IT0049 - M8 - Laravel Full CRUD, Auth, and Email Notifications.pdf", "pages": 35, "notes": [{"title": "The seven resource actions", "body": "index = list; create = new form; store = insert; show = details; edit = edit form; update = save edits; destroy = delete.", "page": 10}, {"title": "Protect resource routes", "body": "Route::middleware('auth')->group(function () {\n    Route::resource('tasks', TaskController::class);\n});", "page": 19}, {"title": "Scope tasks to their owner", "body": "$request->user()->tasks()->create($validated);\n$tasks = $request->user()->tasks()->latest()->get();\n// User: hasMany(Task::class); tasks table: user_id foreign key.", "page": 21}, {"title": "A mailable has a view", "body": "php artisan make:mail TaskCompletedMail --markdown=mail.tasks.completed\n// app/Mail/TaskCompletedMail.php\n// resources/views/mail/tasks/completed.blade.php", "page": 26}, {"title": "Send after the successful update", "body": "if ($task->wasChanged('status') && $task->status === 'done') {\n    Mail::to($request->user()->email)\n        ->send(new TaskCompletedMail($task));\n}", "page": 33}, {"title": "Read classroom examples in context", "body": "Breeze is the scaffold shown in this module. SMTP settings live in .env. Authentication protects entry; checking the owner of a specific record remains a separate access decision.", "page": 18}]}], "questions": [{"id": "m1q1", "module": 1, "page": 8, "topic": "Frameworks", "prompt": "Why use a web application framework?", "answer": "To reuse tools for repetitive web tasks", "choices": ["To reuse tools for repetitive web tasks", "To run PHP entirely in the browser", "To eliminate all application logic", "To replace the database with HTML"], "explanation": "The module describes routing, database access, validation, and organization as repeated tasks a framework helps handle."}, {"id": "m1q2", "module": 1, "page": 12, "topic": "MVC", "prompt": "Which MVC component manages data and business rules?", "answer": "Model", "choices": ["Model", "View", "Controller", "Browser"], "explanation": "The Model retrieves and changes data and holds business rules; it does not handle HTML presentation."}, {"id": "m1q3", "module": 1, "page": 14, "topic": "MVC", "prompt": "Which MVC component coordinates the request, Model, and View?", "answer": "Controller", "choices": ["Controller", "Model", "View", "Database"], "explanation": "The Controller receives the request, asks the Model for data, and passes data to a View."}, {"id": "m1q4", "module": 1, "page": 13, "topic": "MVC", "prompt": "Which folder contains CodeIgniter view templates?", "answer": "app/Views", "choices": ["app/Views", "resources/views", "app/Models", "app/Http/Controllers"], "explanation": "CodeIgniter views are PHP templates in app/Views. resources/views belongs to Laravel."}, {"id": "m1q5", "module": 1, "page": 22, "topic": "Setup", "prompt": "Which command creates the module’s CodeIgniter starter project?", "answer": "composer create-project codeigniter4/appstarter myproject", "choices": ["composer create-project codeigniter4/appstarter myproject", "laravel new myproject", "php spark make:project myproject", "php artisan create-project myproject"], "explanation": "Composer downloads the codeigniter4/appstarter package into the new project folder."}, {"id": "m1q6", "module": 1, "page": 26, "topic": "Structure", "prompt": "Which directory should be the web server document root?", "answer": "public/", "choices": ["public/", "app/", "writable/", "vendor/"], "explanation": "Only public/ should be directly web accessible. Application files, logs, and dependencies stay outside it."}, {"id": "m1q7", "module": 1, "page": 27, "topic": "CLI", "prompt": "Which command starts CodeIgniter’s development server?", "answer": "php spark serve", "choices": ["php spark serve", "php artisan serve", "composer serve codeigniter", "php spark routes"], "explanation": "Spark is CodeIgniter’s command-line tool; serve starts the development server."}, {"id": "m1q8", "module": 1, "page": 34, "topic": "Routing", "prompt": "Where are the module’s explicit CodeIgniter routes defined?", "answer": "app/Config/Routes.php", "choices": ["app/Config/Routes.php", "routes/web.php", "app/Controllers/Routes.php", "public/routes.php"], "explanation": "Routes.php maps requested URLs to controller actions."}, {"id": "m1q9", "module": 1, "page": 35, "topic": "Routing", "prompt": "What does 'Pages::about' identify in a route?", "answer": "The about() method of the Pages controller", "choices": ["The about() method of the Pages controller", "The Pages view inside the about folder", "The Pages database table", "The about() method of the Model class"], "explanation": "The text before :: is the controller and the text after it is its action method."}, {"id": "m1q10", "module": 1, "page": 37, "topic": "Routing", "prompt": "In '/profile/(:num)' → 'Pages::profile/$1', what is $1?", "answer": "The first captured route value", "choices": ["The first captured route value", "The number of controllers", "The database connection index", "A literal dollar amount"], "explanation": "The numeric URL segment is captured and passed as the first argument to profile()."}, {"id": "m1q11", "module": 1, "page": 38, "topic": "Routing", "prompt": "Which route placeholder restricts a match to a single segment without a slash?", "answer": "(:segment)", "choices": ["(:segment)", "(:any)", "(:alpha)", "(:num)"], "explanation": "(:segment) excludes forward slashes; (:any) may include multiple segments."}, {"id": "m1q12", "module": 1, "page": 39, "topic": "Controllers", "prompt": "Which base class is used by the module’s CodeIgniter controllers?", "answer": "BaseController", "choices": ["BaseController", "Eloquent", "Mailable", "TaskModel"], "explanation": "The module’s controller classes extend BaseController."}, {"id": "m1q13", "module": 1, "page": 45, "topic": "Views", "prompt": "Which helper renders a CodeIgniter view?", "answer": "view()", "choices": ["view()", "route()", "model()", "session()"], "explanation": "view() loads a template from app/Views and renders it."}, {"id": "m1q14", "module": 1, "page": 49, "topic": "Views", "prompt": "If a controller passes ['name' => 'Pages'] to view(), what variable is available?", "answer": "$name", "choices": ["$name", "$data->name", "$Pages", "$view[0]"], "explanation": "Each key in the data array becomes a variable inside the view."}, {"id": "m1q15", "module": 1, "page": 50, "topic": "Views", "prompt": "How does the example combine header, menu, main, and footer views?", "answer": "Concatenate view() results with .", "choices": ["Concatenate view() results with .", "Join route definitions with +", "Call findAll() on each template", "Move every view into the controller"], "explanation": "The PHP concatenation operator . joins the rendered view strings into one response."}, {"id": "m1q16", "module": 1, "page": 51, "topic": "Views", "prompt": "Which view name loads app/Views/directory-name/about.php?", "answer": "directory-name/about", "choices": ["directory-name/about", "directory-name.about", "app/Views/directory-name/about.php", "about/directory-name"], "explanation": "The CodeIgniter view name includes its relative subdirectory with a slash."}, {"id": "m2q1", "module": 2, "page": 6, "topic": "Persistence", "prompt": "Why does a task manager need a database?", "answer": "To persist records across requests and restarts", "choices": ["To persist records across requests and restarts", "To replace controller methods", "To display only fixed arrays", "To store HTML only in sessions"], "explanation": "A database stores persistent, shared records instead of temporary page values."}, {"id": "m2q2", "module": 2, "page": 10, "topic": "Configuration", "prompt": "Which driver is shown for the CodeIgniter MySQL connection?", "answer": "MySQLi", "choices": ["MySQLi", "sqlite", "Eloquent", "Blade"], "explanation": "The .env example uses database.default.DBDriver = MySQLi."}, {"id": "m2q3", "module": 2, "page": 12, "topic": "Configuration", "prompt": "When a matching database key is set in both .env and Database.php, which takes precedence?", "answer": ".env", "choices": [".env", "Database.php", "Routes.php", "The view template"], "explanation": "The matching .env value overrides the fallback configured in app/Config/Database.php."}, {"id": "m2q4", "module": 2, "page": 13, "topic": "Configuration", "prompt": "Why keep database credentials in an uncommitted .env file?", "answer": "They differ by environment and should stay out of shared code", "choices": ["They differ by environment and should stay out of shared code", "They are encrypted automatically by every editor", "They must be visible in a public URL", "They replace all database validation"], "explanation": "The module separates local credentials from application code to reduce accidental sharing."}, {"id": "m2q5", "module": 2, "page": 15, "topic": "Troubleshooting", "prompt": "What should you check first for a database 'Connection refused' error in the module’s XAMPP setup?", "answer": "Whether MySQL is running", "choices": ["Whether MySQL is running", "Whether the Blade filename ends in .php", "Whether a task has a title", "Whether the route uses a numeric placeholder"], "explanation": "A stopped MySQL service is the module’s listed cause of a refused database connection."}, {"id": "m2q6", "module": 2, "page": 19, "topic": "Models", "prompt": "Which built-in class does TaskModel extend?", "answer": "CodeIgniter\\Model", "choices": ["CodeIgniter\\Model", "BaseController", "Illuminate\\Http\\Request", "FilterInterface"], "explanation": "TaskModel extends CodeIgniter’s Model to inherit common record operations."}, {"id": "m2q7", "module": 2, "page": 20, "topic": "Models", "prompt": "Which model property selects the database table?", "answer": "$table", "choices": ["$table", "$primaryKey", "$allowedFields", "$baseURL"], "explanation": "protected $table = 'tasks' identifies the table managed by TaskModel."}, {"id": "m2q8", "module": 2, "page": 20, "topic": "Models", "prompt": "Which property allows specified columns to be saved from input?", "answer": "$allowedFields", "choices": ["$allowedFields", "$fillable", "$primaryKey", "$indexPage"], "explanation": "CodeIgniter uses $allowedFields. Laravel’s corresponding mass-assignment list is $fillable."}, {"id": "m2q9", "module": 2, "page": 22, "topic": "Queries", "prompt": "Which model call retrieves all task rows?", "answer": "$model->findAll()", "choices": ["$model->findAll()", "$model->find(1)", "$model->delete(1)", "$model->first()"], "explanation": "findAll() returns multiple records; find($id) retrieves a record by primary key."}, {"id": "m2q10", "module": 2, "page": 23, "topic": "Queries", "prompt": "Which model call retrieves the row with primary key 3?", "answer": "$model->find(3)", "choices": ["$model->find(3)", "$model->findAll(3)", "$model->orderBy(3)", "$model->like(3)"], "explanation": "find(3) looks up the primary key value 3."}, {"id": "m2q11", "module": 2, "page": 24, "topic": "Queries", "prompt": "What does $model->where('status', 'pending')->findAll() return?", "answer": "Only rows whose status is pending", "choices": ["Only rows whose status is pending", "Every row sorted by title", "Only the row with id pending", "The number of pending rows"], "explanation": "where() filters the rows; findAll() retrieves the matching records."}, {"id": "m2q12", "module": 2, "page": 25, "topic": "Queries", "prompt": "What is the effect of orderBy('created_at', 'DESC')?", "answer": "Newest creation dates first", "choices": ["Newest creation dates first", "Oldest creation dates first", "Alphabetical title order", "Only completed tasks"], "explanation": "Descending creation timestamps place the most recent records first."}, {"id": "m2q13", "module": 2, "page": 27, "topic": "Queries", "prompt": "Which method counts matching rows rather than retrieving them?", "answer": "countAllResults()", "choices": ["countAllResults()", "findAll()", "orderBy()", "like()"], "explanation": "countAllResults() returns the count of matching results."}, {"id": "m2q14", "module": 2, "page": 30, "topic": "Views", "prompt": "Why does the example print esc($task['title'])?", "answer": "To escape output before displaying it", "choices": ["To escape output before displaying it", "To encrypt the task in the database", "To sort the task list", "To start a database connection"], "explanation": "esc() prepares text for safe output in the view; it is separate from database querying."}, {"id": "m2q15", "module": 2, "page": 32, "topic": "Views", "prompt": "What variable is created by view('tasks/show', ['task' => $task])?", "answer": "$task", "choices": ["$task", "$tasks", "$show", "$TaskModel"], "explanation": "The array key task becomes the $task variable inside the show view."}, {"id": "m2q16", "module": 2, "page": 34, "topic": "Missing records", "prompt": "What does CodeIgniter find($id) return when the row does not exist?", "answer": "null", "choices": ["null", "An automatic 404 response", "An empty HTML page", "The last row in the table"], "explanation": "The controller must check for null and deliberately respond with a not-found exception."}, {"id": "m3q1", "module": 3, "page": 7, "topic": "Routes", "prompt": "Which command lists registered CodeIgniter routes?", "answer": "php spark routes", "choices": ["php spark routes", "php artisan route:list", "php spark serve", "composer routes:list"], "explanation": "php spark routes helps confirm that the GET and POST routes were registered."}, {"id": "m3q2", "module": 3, "page": 7, "topic": "Forms", "prompt": "In the module’s add-task flow, what does GET /tasks/new do?", "answer": "Displays the new-task form", "choices": ["Displays the new-task form", "Inserts a new task", "Deletes an existing task", "Moves an uploaded file"], "explanation": "GET shows the form; POST /tasks receives the submitted task."}, {"id": "m3q3", "module": 3, "page": 8, "topic": "CSRF", "prompt": "Which CodeIgniter helper inserts the hidden CSRF token field?", "answer": "csrf_field()", "choices": ["csrf_field()", "@csrf", "old()", "base_url()"], "explanation": "csrf_field() adds a token field for CSRF protection when the corresponding protection is enabled."}, {"id": "m3q4", "module": 3, "page": 10, "topic": "Validation", "prompt": "What does required|min_length[3]|max_length[150] require?", "answer": "A nonempty value between 3 and 150 characters", "choices": ["A nonempty value between 3 and 150 characters", "Exactly 150 numeric digits", "An optional value below 3 characters", "A file smaller than 150 KB"], "explanation": "The rules require a value and set its minimum and maximum string lengths."}, {"id": "m3q5", "module": 3, "page": 11, "topic": "Validation", "prompt": "Which CodeIgniter rule checks whether a task title is already in the table?", "answer": "is_unique[tasks.title]", "choices": ["is_unique[tasks.title]", "valid_email", "max_size[title,150]", "uploaded[title]"], "explanation": "is_unique[tasks.title] checks uniqueness against the title column in tasks."}, {"id": "m3q6", "module": 3, "page": 12, "topic": "Validation", "prompt": "What does redirect()->back()->withInput() preserve after failure?", "answer": "The submitted form input for redisplay", "choices": ["The submitted form input for redisplay", "A permanent login session", "The database schema", "The uploaded file bytes in an input element"], "explanation": "withInput() makes previous input available when the form is shown again."}, {"id": "m3q7", "module": 3, "page": 14, "topic": "Feedback", "prompt": "Which helper displays the validation error for the title field?", "answer": "validation_show_error('title')", "choices": ["validation_show_error('title')", "csrf_field('title')", "find('title')", "getRandomName('title')"], "explanation": "validation_show_error() displays a field error; old() restores its previous value."}, {"id": "m3q8", "module": 3, "page": 18, "topic": "CRUD", "prompt": "Which model method inserts a new task row?", "answer": "insert()", "choices": ["insert()", "find()", "orderBy()", "delete()"], "explanation": "After validation, insert() writes a new row through the Model."}, {"id": "m3q9", "module": 3, "page": 19, "topic": "CRUD", "prompt": "Which call changes one existing task by id?", "answer": "$model->update($id, $data)", "choices": ["$model->update($id, $data)", "$model->findAll($data)", "$model->first($id)", "$model->countAllResults($id)"], "explanation": "update() receives the target primary key and the fields to change."}, {"id": "m3q10", "module": 3, "page": 20, "topic": "HTTP methods", "prompt": "Which approach matches the module’s clean delete workflow?", "answer": "Submit a POST form to a delete action", "choices": ["Submit a POST form to a delete action", "Delete through a normal GET link", "Delete inside a view foreach loop", "Delete before validating the request"], "explanation": "The module avoids destructive actions on GET and uses submitted requests for record changes."}, {"id": "m3q11", "module": 3, "page": 22, "topic": "Old input", "prompt": "What does old('title', $task['title']) prefer?", "answer": "Failed submitted input, then the saved title", "choices": ["Failed submitted input, then the saved title", "The saved title, then failed input", "Always an empty value", "Always a new database query"], "explanation": "The first argument names old input; the second provides the saved fallback."}, {"id": "m3q12", "module": 3, "page": 25, "topic": "Uploads", "prompt": "Which form encoding is required to send file bytes?", "answer": "multipart/form-data", "choices": ["multipart/form-data", "application/json", "text/plain", "application/sql"], "explanation": "The file upload form must use enctype=\"multipart/form-data\"."}, {"id": "m3q13", "module": 3, "page": 26, "topic": "Uploads", "prompt": "Which CodeIgniter file rule checks that attachment was uploaded?", "answer": "uploaded[attachment]", "choices": ["uploaded[attachment]", "required[attachment]", "image:attachment", "valid_email[attachment]"], "explanation": "The module uses file-specific rules: uploaded, max_size, and mime_in."}, {"id": "m3q14", "module": 3, "page": 27, "topic": "Uploads", "prompt": "Which method generates a safer server-side upload name?", "answer": "getRandomName()", "choices": ["getRandomName()", "getPost()", "findAll()", "setFlashdata()"], "explanation": "A generated name avoids relying on a user-supplied original filename."}, {"id": "m3q15", "module": 3, "page": 29, "topic": "Uploads", "prompt": "Where does move(FCPATH . 'uploads', $newName) place the file in the example?", "answer": "public/uploads", "choices": ["public/uploads", "app/Views/uploads", "vendor/uploads", "database/uploads"], "explanation": "FCPATH points to the front-controller directory, which is public/ in the module’s layout."}, {"id": "m3q16", "module": 3, "page": 31, "topic": "Uploads", "prompt": "What does the module save in the task attachment column?", "answer": "The generated filename", "choices": ["The generated filename", "The full file bytes", "The upload form HTML", "The user’s password"], "explanation": "The file lives on disk; the database stores its filename so the view can construct a URL."}, {"id": "m4q1", "module": 4, "page": 6, "topic": "Sessions", "prompt": "What problem do sessions solve for HTTP applications?", "answer": "Remembering small visitor values across separate requests", "choices": ["Remembering small visitor values across separate requests", "Making every HTTP request permanent", "Replacing all database records", "Executing PHP inside browser cookies"], "explanation": "HTTP requests are separate; sessions connect small pieces of state to a visitor."}, {"id": "m4q2", "module": 4, "page": 8, "topic": "Sessions", "prompt": "Which call stores a CodeIgniter session value?", "answer": "session()->set('username', 'admin')", "choices": ["session()->set('username', 'admin')", "session()->find('username')", "session()->insert('admin')", "session()->where('username')"], "explanation": "set() stores a value; get() or session('username') retrieves it."}, {"id": "m4q3", "module": 4, "page": 9, "topic": "Sessions", "prompt": "Which method removes just one session value?", "answer": "remove()", "choices": ["remove()", "destroy()", "get()", "getFlashdata()"], "explanation": "remove() targets a key, whereas destroy() clears the session."}, {"id": "m4q4", "module": 4, "page": 9, "topic": "Logout", "prompt": "Which session method does the module use during logout?", "answer": "destroy()", "choices": ["destroy()", "get()", "setFlashdata()", "first()"], "explanation": "Logout destroys the session so the stored login state ends."}, {"id": "m4q5", "module": 4, "page": 10, "topic": "Flash data", "prompt": "What is flash data intended for?", "answer": "A message available on the next request after a redirect", "choices": ["A message available on the next request after a redirect", "A permanent password store", "A table of all users", "A replacement for an image upload"], "explanation": "Flash data lasts one subsequent request by default, making it suitable for redirect feedback."}, {"id": "m4q6", "module": 4, "page": 11, "topic": "Flash data", "prompt": "Which method reads a one-time message?", "answer": "getFlashdata()", "choices": ["getFlashdata()", "setFlashdata()", "password_verify()", "getRandomName()"], "explanation": "getFlashdata('message') retrieves the message set before the redirect."}, {"id": "m4q7", "module": 4, "page": 13, "topic": "Session safety", "prompt": "Which value is appropriate to store in the login session?", "answer": "user_id", "choices": ["user_id", "Plain-text password", "The entire users table", "An uploaded video file"], "explanation": "The module recommends small identifiers and login state, never passwords or large records."}, {"id": "m4q8", "module": 4, "page": 19, "topic": "Passwords", "prompt": "Which function creates a password hash?", "answer": "password_hash()", "choices": ["password_hash()", "password_verify()", "esc()", "base_url()"], "explanation": "password_hash($plainPassword, PASSWORD_DEFAULT) produces the hash stored in the database."}, {"id": "m4q9", "module": 4, "page": 24, "topic": "Passwords", "prompt": "Which function checks a typed password against the stored hash?", "answer": "password_verify()", "choices": ["password_verify()", "password_hash()", "strcmp()", "getFlashdata()"], "explanation": "password_verify($password, $storedHash) checks the password; a direct equality comparison is unsuitable."}, {"id": "m4q10", "module": 4, "page": 23, "topic": "Login", "prompt": "Why use $model->where('username', $username)->first()?", "answer": "To retrieve the user matching the submitted username", "choices": ["To retrieve the user matching the submitted username", "To hash every username", "To delete duplicate users", "To return every task owned by a user"], "explanation": "The login controller first looks up the user, then verifies the password hash."}, {"id": "m4q11", "module": 4, "page": 25, "topic": "Login", "prompt": "What should follow a successful password check in the sample?", "answer": "Store small login values and redirect to /tasks", "choices": ["Store small login values and redirect to /tasks", "Store the password in the session", "Return the password hash to the browser", "Delete the users table"], "explanation": "The sample stores isLoggedIn, user_id, and username, then redirects."}, {"id": "m4q12", "module": 4, "page": 27, "topic": "Filters", "prompt": "When does an authentication filter’s before() check run?", "answer": "Before the controller action", "choices": ["Before the controller action", "After the response is displayed", "Only during database migration", "Only when rendering CSS"], "explanation": "The before() method can redirect a guest before protected controller logic runs."}, {"id": "m4q13", "module": 4, "page": 29, "topic": "Filters", "prompt": "Which interface does AuthFilter implement?", "answer": "FilterInterface", "choices": ["FilterInterface", "Mailable", "BaseController", "TaskModel"], "explanation": "The filter implements CodeIgniter\\Filters\\FilterInterface and defines before() and after()."}, {"id": "m4q14", "module": 4, "page": 30, "topic": "Filters", "prompt": "Where is the auth filter alias registered?", "answer": "app/Config/Filters.php", "choices": ["app/Config/Filters.php", "routes/web.php", "resources/views/auth.php", "app/Models/UserModel.php"], "explanation": "Filters.php maps the short auth alias to the AuthFilter class."}, {"id": "m4q15", "module": 4, "page": 31, "topic": "Access control", "prompt": "What does ['filter' => 'auth'] on a CodeIgniter route do?", "answer": "Applies the registered authentication filter", "choices": ["Applies the registered authentication filter", "Creates the users table", "Hashes all submitted values", "Assigns an administrator role"], "explanation": "The alias attaches the filter to the route so login state can be checked."}, {"id": "m4q16", "module": 4, "page": 31, "topic": "Access control", "prompt": "Does a basic login filter also establish role-based permissions?", "answer": "No; role checks are additional", "choices": ["No; role checks are additional", "Yes; every logged-in user becomes an administrator", "Yes; roles are inferred from the URL", "Only when the view contains a password field"], "explanation": "The module distinguishes authentication-based access from additional role-based permissions."}, {"id": "m5q1", "module": 5, "page": 6, "topic": "Frameworks", "prompt": "What is the module’s main link between CodeIgniter and Laravel?", "answer": "They use the same MVC responsibilities", "choices": ["They use the same MVC responsibilities", "They use identical folder names", "Laravel executes only in the browser", "CodeIgniter views are Blade templates"], "explanation": "Laravel is more convention-driven, but the MVC responsibilities transfer from CodeIgniter."}, {"id": "m5q2", "module": 5, "page": 7, "topic": "Setup", "prompt": "After installing the Laravel installer, which command creates the sample project?", "answer": "laravel new myproject", "choices": ["laravel new myproject", "php artisan new myproject", "php spark serve myproject", "composer migrate myproject"], "explanation": "The module installs laravel/installer globally and then runs laravel new myproject."}, {"id": "m5q3", "module": 5, "page": 9, "topic": "Structure", "prompt": "Where do normal Laravel web routes live?", "answer": "routes/web.php", "choices": ["routes/web.php", "app/Config/Routes.php", "resources/routes.php", "app/Http/Views.php"], "explanation": "The conventional web routes file is routes/web.php."}, {"id": "m5q4", "module": 5, "page": 9, "topic": "Structure", "prompt": "Where are Laravel controllers stored?", "answer": "app/Http/Controllers", "choices": ["app/Http/Controllers", "app/Controllers", "resources/controllers", "database/controllers"], "explanation": "Laravel’s controller folder includes the Http subdirectory."}, {"id": "m5q5", "module": 5, "page": 9, "topic": "Blade", "prompt": "Where are Blade views stored?", "answer": "resources/views", "choices": ["resources/views", "app/Views", "routes/views", "public/Models"], "explanation": "Laravel templates live in resources/views and use the .blade.php extension."}, {"id": "m5q6", "module": 5, "page": 11, "topic": "Configuration", "prompt": "Which .env setting specifies the application URL?", "answer": "APP_URL", "choices": ["APP_URL", "app.baseURL", "DB_CONNECTION", "MAIL_HOST"], "explanation": "Laravel uses APP_URL, while the CodeIgniter examples use app.baseURL."}, {"id": "m5q7", "module": 5, "page": 13, "topic": "CLI", "prompt": "Which command starts the simple Laravel development server?", "answer": "php artisan serve", "choices": ["php artisan serve", "php spark serve", "php artisan migrate", "laravel route:list"], "explanation": "Artisan is Laravel’s command-line tool. Its serve command runs the local development server."}, {"id": "m5q8", "module": 5, "page": 21, "topic": "Routing", "prompt": "Which route helper serves a static about Blade view directly?", "answer": "Route::view('/about', 'about')", "choices": ["Route::view('/about', 'about')", "Route::model('/about', 'about')", "Route::delete('/about', 'about')", "Route::mail('/about', 'about')"], "explanation": "Route::view is useful for simple pages that do not yet need controller logic."}, {"id": "m5q9", "module": 5, "page": 23, "topic": "Routing", "prompt": "In Route::get('/tasks/{id}', function ($id) {...}), what does {id} represent?", "answer": "A URL parameter passed into the handler", "choices": ["A URL parameter passed into the handler", "A session key automatically encrypted", "A literal pair of curly braces in the URL", "A migration identifier"], "explanation": "Visiting /tasks/15 passes the URL value 15 into the handler."}, {"id": "m5q10", "module": 5, "page": 24, "topic": "CLI", "prompt": "Which command generates PageController?", "answer": "php artisan make:controller PageController", "choices": ["php artisan make:controller PageController", "php spark make:blade PageController", "laravel make:view PageController", "composer controller PageController"], "explanation": "Artisan generates the controller in app/Http/Controllers."}, {"id": "m5q11", "module": 5, "page": 26, "topic": "CLI", "prompt": "Which command inspects registered Laravel routes?", "answer": "php artisan route:list", "choices": ["php artisan route:list", "php spark routes", "php artisan db:seed", "php artisan storage:link"], "explanation": "route:list shows Laravel’s registered routes."}, {"id": "m5q12", "module": 5, "page": 27, "topic": "Routing", "prompt": "What does [PageController::class, 'about'] identify?", "answer": "A controller class and its action method", "choices": ["A controller class and its action method", "A Blade view and its CSS class", "A model and its primary key", "A database and its connection driver"], "explanation": "The route calls about() on PageController; the controller class is imported into the route file."}, {"id": "m5q13", "module": 5, "page": 28, "topic": "View data", "prompt": "What is passed as the second argument of view() to supply named variables?", "answer": "An associative array", "choices": ["An associative array", "An SMTP connection", "A migration file", "A session cookie"], "explanation": "The keys in the data array become variables that Blade can display."}, {"id": "m5q14", "module": 5, "page": 29, "topic": "Blade", "prompt": "Which filename follows the module’s Laravel about-view convention?", "answer": "about.blade.php", "choices": ["about.blade.php", "about.php", "about.controller.php", "about.sql"], "explanation": "Blade templates use .blade.php inside resources/views."}, {"id": "m5q15", "module": 5, "page": 32, "topic": "Blade", "prompt": "Which syntax escapes normal Blade output?", "answer": "{{ $title }}", "choices": ["{{ $title }}", "{!! $title !!}", "<?raw $title ?>", "@method($title)"], "explanation": "Double curly braces escape values; {!! !!} is raw output."}, {"id": "m5q16", "module": 5, "page": 20, "topic": "Framework comparison", "prompt": "Which helper name is shared by the two frameworks’ view examples?", "answer": "view()", "choices": ["view()", "csrf_field()", "findAll()", "Route::resource()"], "explanation": "Both frameworks use view(), though template folders and other conventions differ."}, {"id": "m6q1", "module": 6, "page": 6, "topic": "Data layer", "prompt": "Which Laravel component describes database table structure changes?", "answer": "Migration", "choices": ["Migration", "Seeder", "Blade view", "Mailable"], "explanation": "Migrations define and version schema; seeders insert sample records."}, {"id": "m6q2", "module": 6, "page": 8, "topic": "Structure", "prompt": "Where are Laravel seeders stored?", "answer": "database/seeders", "choices": ["database/seeders", "app/Views", "routes/seeders", "public/database"], "explanation": "Laravel separates database/migrations, database/seeders, and app/Models."}, {"id": "m6q3", "module": 6, "page": 10, "topic": "Migrations", "prompt": "Which migration helper adds created_at and updated_at columns?", "answer": "$table->timestamps()", "choices": ["$table->timestamps()", "$table->id()", "$table->nullable()", "$table->default()"], "explanation": "timestamps() creates the pair of timestamp columns."}, {"id": "m6q4", "module": 6, "page": 11, "topic": "Migrations", "prompt": "Which column modifier permits an empty database value represented by NULL?", "answer": "nullable()", "choices": ["nullable()", "timestamps()", "constrained()", "default(false)"], "explanation": "nullable() allows NULL; it is separate from setting a default value."}, {"id": "m6q5", "module": 6, "page": 12, "topic": "CLI", "prompt": "Which command runs pending Laravel migrations?", "answer": "php artisan migrate", "choices": ["php artisan migrate", "php artisan make:model", "php spark migrate:tasks", "php artisan route:list"], "explanation": "migrate applies migrations that have not yet run."}, {"id": "m6q6", "module": 6, "page": 12, "topic": "CLI", "prompt": "What does php artisan migrate:rollback undo?", "answer": "The last batch of migrations", "choices": ["The last batch of migrations", "Only the most recent inserted row", "Every uploaded file", "All route registrations"], "explanation": "rollback reverses the last migration batch."}, {"id": "m6q7", "module": 6, "page": 12, "topic": "CLI", "prompt": "What does php artisan migrate:fresh do?", "answer": "Rebuilds all tables from zero", "choices": ["Rebuilds all tables from zero", "Only retrieves existing tables", "Adds a new task without schema changes", "Runs a read-only connection test"], "explanation": "fresh drops tables and reruns migrations, so the module reserves destructive resets for local development."}, {"id": "m6q8", "module": 6, "page": 13, "topic": "Seeders", "prompt": "What is the purpose of TaskSeeder?", "answer": "Insert predictable sample task records", "choices": ["Insert predictable sample task records", "Define HTTP routes", "Render a task list", "Send a completion email"], "explanation": "Seeders make demos and debugging repeatable by providing known data."}, {"id": "m6q9", "module": 6, "page": 18, "topic": "Eloquent", "prompt": "Which command generates the Task model?", "answer": "php artisan make:model Task", "choices": ["php artisan make:model Task", "php artisan make:view Task", "php spark make:eloquent Task", "laravel seed Task"], "explanation": "The model is generated as app/Models/Task.php."}, {"id": "m6q10", "module": 6, "page": 19, "topic": "Eloquent", "prompt": "Which Eloquent model property allows fields for mass assignment?", "answer": "$fillable", "choices": ["$fillable", "$allowedFields", "$baseURL", "$aliases"], "explanation": "The module lists title and status in $fillable for create() and update()."}, {"id": "m6q11", "module": 6, "page": 21, "topic": "Eloquent", "prompt": "Which Eloquent call retrieves all task records?", "answer": "Task::all()", "choices": ["Task::all()", "Task::create([])", "Task::findOrFail(1)", "Task::latest()"], "explanation": "Task::all() retrieves all records; latest() alone still describes a query."}, {"id": "m6q12", "module": 6, "page": 21, "topic": "View data", "prompt": "What does compact('tasks') create?", "answer": "An array with the key tasks and the value of $tasks", "choices": ["An array with the key tasks and the value of $tasks", "A compressed database archive", "A new Task model", "A hidden CSRF field"], "explanation": "PHP compact() builds an array from existing variable names."}, {"id": "m6q13", "module": 6, "page": 24, "topic": "Eloquent", "prompt": "Which method executes the filtered query Task::where(...)->orderBy(...)?", "answer": "get()", "choices": ["get()", "view()", "rules()", "content()"], "explanation": "where() filters, orderBy() sorts, and get() retrieves the matching results."}, {"id": "m6q14", "module": 6, "page": 25, "topic": "Missing records", "prompt": "What happens when Task::findOrFail($id) cannot find a task?", "answer": "A not-found exception produces a 404 response", "choices": ["A not-found exception produces a 404 response", "It returns the first task", "It creates a task with that id", "It returns the string false"], "explanation": "findOrFail() is used when a missing row should become a 404 page."}, {"id": "m6q15", "module": 6, "page": 23, "topic": "Blade", "prompt": "Which expression accesses a Task object’s title in Blade?", "answer": "{{ $task->title }}", "choices": ["{{ $task->title }}", "{{ $tasks.title }}", "{{ title($task) }}", "{{ Task::title }}"], "explanation": "The module’s Eloquent records are model objects displayed with -> property access."}, {"id": "m6q16", "module": 6, "page": 32, "topic": "Debugging", "prompt": "Which command opens Laravel’s interactive environment for quick model checks?", "answer": "php artisan tinker", "choices": ["php artisan tinker", "php artisan serve", "php spark routes", "php artisan storage:link"], "explanation": "Tinker lets you inspect records with calls such as Task::count() and Task::first()."}, {"id": "m7q1", "module": 7, "page": 6, "topic": "Forms", "prompt": "Which HTTP method displays the module’s create form?", "answer": "GET", "choices": ["GET", "POST", "PATCH", "DELETE"], "explanation": "GET shows the form, while POST sends its data to the controller."}, {"id": "m7q2", "module": 7, "page": 8, "topic": "Routes", "prompt": "Which controller method receives POST /tasks in the example?", "answer": "store", "choices": ["store", "create", "edit", "index"], "explanation": "create displays the form; store receives and saves the submitted data."}, {"id": "m7q3", "module": 7, "page": 9, "topic": "CSRF", "prompt": "Which Blade directive inserts the CSRF token field?", "answer": "@csrf", "choices": ["@csrf", "csrf_field[]", "@method", "@error"], "explanation": "@csrf is included in the module’s state-changing web forms."}, {"id": "m7q4", "module": 7, "page": 11, "topic": "Request", "prompt": "Which class is injected as the current request?", "answer": "Illuminate\\Http\\Request", "choices": ["Illuminate\\Http\\Request", "App\\Models\\Task", "CodeIgniter\\Model", "Illuminate\\Mail\\Mailable"], "explanation": "A controller imports Illuminate\\Http\\Request and accepts Request $request."}, {"id": "m7q5", "module": 7, "page": 12, "topic": "Validation", "prompt": "What does $request->validate() do on failed validation in this web-form workflow?", "answer": "Redirects back with errors and old input", "choices": ["Redirects back with errors and old input", "Saves invalid fields anyway", "Deletes the current task", "Silently accepts every field"], "explanation": "Laravel returns the user to the form with errors and prior input."}, {"id": "m7q6", "module": 7, "page": 13, "topic": "Validation", "prompt": "What does ['required', 'string', 'max:100'] mean for title?", "answer": "A required string no longer than 100 characters", "choices": ["A required string no longer than 100 characters", "An optional image below 100 KB", "Exactly 100 records must exist", "A numeric id of at least 100"], "explanation": "Validation rules should fit the application’s field requirements."}, {"id": "m7q7", "module": 7, "page": 14, "topic": "Feedback", "prompt": "Which Blade directive checks for a title validation error?", "answer": "@error('title')", "choices": ["@error('title')", "@csrf('title')", "@method('title')", "@foreach('title')"], "explanation": "Inside @error('title'), $message contains the validation message."}, {"id": "m7q8", "module": 7, "page": 19, "topic": "Model binding", "prompt": "In edit(Task $task), what does the route-bound Task represent?", "answer": "The existing task selected by the route parameter", "choices": ["The existing task selected by the route parameter", "A new empty record every time", "The entire tasks collection", "The current uploaded image"], "explanation": "The route uses {task}, and the controller receives the selected Task model."}, {"id": "m7q9", "module": 7, "page": 22, "topic": "HTTP methods", "prompt": "Which directive makes an HTML POST form target the PATCH update route?", "answer": "@method('PATCH')", "choices": ["@method('PATCH')", "@patch", "@csrf('PATCH')", "@route('PATCH')"], "explanation": "The form uses method=\"POST\" plus @method('PATCH') for method spoofing."}, {"id": "m7q10", "module": 7, "page": 22, "topic": "Old input", "prompt": "What does old('title', $task->title) show after a failed submission?", "answer": "The submitted title, with the saved title as fallback", "choices": ["The submitted title, with the saved title as fallback", "Always the original saved title", "Always an empty string", "The newest title in the whole database"], "explanation": "old() prioritizes prior form input and otherwise uses the existing record value."}, {"id": "m7q11", "module": 7, "page": 24, "topic": "Uploads", "prompt": "In file validation, what does max:2048 mean?", "answer": "A maximum of 2048 KB", "choices": ["A maximum of 2048 KB", "A maximum of 2048 characters", "Exactly 2048 image pixels", "A minimum of 2048 bytes"], "explanation": "For uploaded files the limit is in kilobytes, approximately 2 MB here."}, {"id": "m7q12", "module": 7, "page": 25, "topic": "Uploads", "prompt": "What does store('attachments', 'public') return for saving in the record?", "answer": "The stored file path", "choices": ["The stored file path", "The raw image bytes", "The current user’s password", "A Blade template instance"], "explanation": "The upload is saved on the public disk; the task stores its generated path."}, {"id": "m7q13", "module": 7, "page": 26, "topic": "Storage", "prompt": "Which command exposes files on the public storage disk through /storage?", "answer": "php artisan storage:link", "choices": ["php artisan storage:link", "php artisan migrate:fresh", "php artisan route:list", "php spark serve"], "explanation": "storage:link creates the public storage link used by the display URL."}, {"id": "m7q14", "module": 7, "page": 27, "topic": "Storage", "prompt": "Which expression builds the module’s public attachment URL?", "answer": "asset('storage/'.$task->attachment)", "choices": ["asset('storage/'.$task->attachment)", "view('storage/'.$task->attachment)", "password_hash($task->attachment)", "old('storage')"], "explanation": "asset() builds the URL through the storage link using the saved relative path."}, {"id": "m7q15", "module": 7, "page": 30, "topic": "Form requests", "prompt": "Which command creates a class for longer validation rules?", "answer": "php artisan make:request UpdateTaskRequest", "choices": ["php artisan make:request UpdateTaskRequest", "php artisan make:mail UpdateTaskRequest", "php spark make:filter UpdateTaskRequest", "php artisan db:seed UpdateTaskRequest"], "explanation": "A Form Request moves rules() out of a crowded controller."}, {"id": "m7q16", "module": 7, "page": 33, "topic": "Replacing files", "prompt": "When should an old attachment be deleted in a reliable replacement workflow?", "answer": "After the replacement succeeds", "choices": ["After the replacement succeeds", "Before validating the new file", "Whenever the form is opened", "Before checking that a new file exists"], "explanation": "The module’s checklist says to clean up old files only after replacement succeeds. Page 28’s short snippet omits that full ordering."}, {"id": "m8q1", "module": 8, "page": 8, "topic": "Resource routes", "prompt": "Which call registers standard Laravel task CRUD routes?", "answer": "Route::resource('tasks', TaskController::class)", "choices": ["Route::resource('tasks', TaskController::class)", "Route::view('tasks', TaskController::class)", "Route::mail('tasks', TaskController::class)", "Route::session('tasks', TaskController::class)"], "explanation": "One resource registration creates the standard routes for index, create, store, show, edit, update, and destroy."}, {"id": "m8q2", "module": 8, "page": 10, "topic": "Resource routes", "prompt": "How many standard actions are listed for a full resource controller?", "answer": "7", "choices": ["7", "4", "5", "8"], "explanation": "The seven actions are index, create, store, show, edit, update, and destroy."}, {"id": "m8q3", "module": 8, "page": 10, "topic": "Resource routes", "prompt": "Which action handles DELETE /tasks/{task}?", "answer": "destroy", "choices": ["destroy", "deleteAll", "remove", "edit"], "explanation": "The resource action and route name are destroy and tasks.destroy."}, {"id": "m8q4", "module": 8, "page": 12, "topic": "Resource methods", "prompt": "Which resource method displays the form for adding a record?", "answer": "create", "choices": ["create", "store", "show", "update"], "explanation": "create shows the form; store validates and inserts the submitted record."}, {"id": "m8q5", "module": 8, "page": 10, "topic": "Resource routes", "prompt": "Which methods match the standard tasks.update route?", "answer": "PUT/PATCH", "choices": ["PUT/PATCH", "GET only", "POST only", "DELETE only"], "explanation": "The module’s resource route table maps PUT or PATCH to update."}, {"id": "m8q6", "module": 8, "page": 11, "topic": "Queries", "prompt": "What does Task::latest()->get() retrieve in the index example?", "answer": "Tasks with the newest first", "choices": ["Tasks with the newest first", "Only tasks marked done", "The current user automatically", "A new empty task"], "explanation": "latest() orders by the creation timestamp, then get() retrieves the records. User scoping is added separately."}, {"id": "m8q7", "module": 8, "page": 13, "topic": "CRUD", "prompt": "What is the order in the store example?", "answer": "Validate → create → redirect", "choices": ["Validate → create → redirect", "Redirect → validate → create", "Create → redirect → validate", "Create → render → delete"], "explanation": "The sample validates request data, calls Task::create($validated), then redirects to tasks.index."}, {"id": "m8q8", "module": 8, "page": 18, "topic": "Authentication", "prompt": "Which classroom auth scaffold is shown in the module?", "answer": "Laravel Breeze with Blade", "choices": ["Laravel Breeze with Blade", "CodeIgniter Shield", "TaskSeeder", "Intervention Image"], "explanation": "The slides use composer require laravel/breeze --dev and php artisan breeze:install blade. This is the module’s classroom workflow."}, {"id": "m8q9", "module": 8, "page": 19, "topic": "Middleware", "prompt": "Which middleware protects the module’s task resource routes?", "answer": "auth", "choices": ["auth", "mail", "storage", "seed"], "explanation": "The resource routes are wrapped in Route::middleware('auth')->group(...)."}, {"id": "m8q10", "module": 8, "page": 21, "topic": "Relationships", "prompt": "Which User relationship supports $request->user()->tasks()->create($validated)?", "answer": "hasMany(Task::class)", "choices": ["hasMany(Task::class)", "belongsTo(Mailable::class)", "view('tasks')", "findAll(Task::class)"], "explanation": "The User model defines a hasMany Task relationship, paired with a user_id foreign key."}, {"id": "m8q11", "module": 8, "page": 22, "topic": "User records", "prompt": "Which query limits the task list to the current user?", "answer": "$request->user()->tasks()->latest()->get()", "choices": ["$request->user()->tasks()->latest()->get()", "Task::all()", "Task::latest()->get()", "Task::findOrFail(1)"], "explanation": "Starting from the current user’s tasks() relationship scopes results by user_id."}, {"id": "m8q12", "module": 8, "page": 25, "topic": "Mail settings", "prompt": "Where does the module keep SMTP connection values?", "answer": ".env", "choices": [".env", "resources/views/tasks/index.blade.php", "public/index.html", "app/Models/Task.php"], "explanation": "MAIL_MAILER, MAIL_HOST, MAIL_PORT, and credentials are environment settings."}, {"id": "m8q13", "module": 8, "page": 26, "topic": "Mail", "prompt": "Which command generates the module’s Markdown mailable?", "answer": "php artisan make:mail TaskCompletedMail --markdown=mail.tasks.completed", "choices": ["php artisan make:mail TaskCompletedMail --markdown=mail.tasks.completed", "php artisan make:model TaskCompletedMail", "php spark make:mail TaskCompletedMail", "php artisan storage:mail TaskCompletedMail"], "explanation": "The command creates a mailable class and its Markdown Blade email view."}, {"id": "m8q14", "module": 8, "page": 28, "topic": "Mail", "prompt": "What does the mailable content() method select?", "answer": "The email’s Markdown view", "choices": ["The email’s Markdown view", "The task table’s primary key", "The login middleware alias", "The CSRF token value"], "explanation": "new Content(markdown: 'mail.tasks.completed') selects the email template."}, {"id": "m8q15", "module": 8, "page": 30, "topic": "Mail", "prompt": "Which call sends the completion mailable to the user?", "answer": "Mail::to($request->user()->email)->send(new TaskCompletedMail($task))", "choices": ["Mail::to($request->user()->email)->send(new TaskCompletedMail($task))", "Task::to($request->user())->findAll()", "Route::mail($task)->get()", "Storage::send($task)"], "explanation": "The Mail facade addresses and sends a TaskCompletedMail instance after a successful update."}, {"id": "m8q16", "module": 8, "page": 33, "topic": "Email triggers", "prompt": "Why check $task->wasChanged('status') && $task->status === 'done'?", "answer": "To send on a change to done instead of every later update", "choices": ["To send on a change to done instead of every later update", "To send before saving the task", "To mark all tasks done", "To bypass authentication"], "explanation": "Checking the changed field plus its new value avoids repeatedly sending completion mail when status has not changed."}]};
